cypress_script:
describe('Asynchronously Loaded Content', () => {
  it('should display the content after clicking the Start button', () => {
    cy.visit('https://the-internet.herokuapp.com/dynamic_loading/1');
    cy.get('div#start button').click();
    cy.get('div#finish').should('be.visible');
  });
  it('should not change the URL if the Start button is not clicked', () => {
    cy.visit('https://the-internet.herokuapp.com/dynamic_loading/1');
    cy.url().should('eq', 'https://the-internet.herokuapp.com/dynamic_loading/1');
    cy.get('div#finish').should('not.exist');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Asynchronously Loaded Content', () => {
  test('should display the content after clicking the Start button', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/dynamic_loading/1');
    await page.click('div#start button');
    await expect(page.locator('div#finish')).toBeVisible();
  });
  test('should not change the URL if the Start button is not clicked', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/dynamic_loading/1');
    await expect(page).toHaveURL('https://the-internet.herokuapp.com/dynamic_loading/1');
    await expect(page.locator('div#finish')).not.toBeVisible();
  });
});
